 dwell=T/(p['jumpCount']+1);action=dwell*sum(a if x==0 else d for x in states);boundary=pi[states[0]]/pi[states[-1]];rho=s.factor(boundary*rateRatio);assert s.factor(rho-forwardWord/reverseWord)==0;total=mp.log(M(rho))
